flow_path = '/work/output/artifacts/skill-flow-devcon-billing-dispute-resolution/BillingDisputeResolution/BillingDisputeResolution/BillingDisputeResolution.flow'
flow = json.load(open(flow_path))

# Fix switch1 node: cases need id + expression, not value+label
for node in flow['nodes']:
    if node['id'] == 'switch1':
        node['inputs'] = {
            'cases': [
                {
                    'id': 'escalate_to_manager',
                    'label': 'Escalate to Manager',
                    'expression': "$vars.disputeAnalyst1.output.recommendedAction === 'escalate_to_manager'"
                },
                {
                    'id': 'auto_resolve',
                    'label': 'Auto Resolve',
                    'expression': "$vars.disputeAnalyst1.output.recommendedAction === 'auto_resolve'"
                },
                {
                    'id': 'reject',
                    'label': 'Reject',
                    'expression': "$vars.disputeAnalyst1.output.recommendedAction === 'reject'"
                }
            ]
        }
        break

# Fix edge sourcePort for switch edges: case-{id}
for edge in flow['edges']:
    if edge['sourceNodeId'] == 'switch1':
        sp = edge['sourcePort']
        if sp in ('escalate_to_manager', 'auto_resolve', 'reject'):
            edge['sourcePort'] = f'case-{sp}'

json.dump(flow, open(flow_path, 'w'), indent=2)
print("Fixed switch1 cases and edges")

# Verify
for edge in flow['edges']:
    if edge['sourceNodeId'] == 'switch1':
        print(f"  switch1 edge: {edge['id']} -> {edge['sourcePort']} -> {edge['targetNodeId']}")
PYEOF

