import json

flow_path = '/work/output/artifacts/skill-flow-devcon-billing-dispute-resolution/BillingDisputeResolution/BillingDisputeResolution/BillingDisputeResolution.flow'
flow = json.load(open(flow_path))

# Get script node IDs
script_nodes = {n['id'] for n in flow['nodes'] if n.get('type') == 'core.action.script'}
print("Script nodes:", script_nodes)

# Fix edges from script nodes: sourcePort "output" -> "success"
for edge in flow['edges']:
    if edge['sourceNodeId'] in script_nodes and edge.get('sourcePort') == 'output':
        print(f"  Fixing edge {edge['id']}: output -> success")
        edge['sourcePort'] = 'success'

json.dump(flow, open(flow_path, 'w'), indent=2)
print("Done")

# Also check what ports merge node has  
for defn in flow['definitions']:
    if defn.get('nodeType') == 'core.logic.merge':
        print("Merge handles:")
        for hc in defn.get('handleConfiguration', []):
            for h in hc.get('handles', []):
                print(f"  {h.get('type')}: {h.get('id')}")

# Check api-workflow node ports  
for defn in flow['definitions']:
    if defn.get('nodeType', '').startswith('uipath.core.api-workflow'):
        print("API-workflow handles:")
        for hc in defn.get('handleConfiguration', []):
            for h in hc.get('handles', []):
                print(f"  {h.get('type')}: {h.get('id')}")
